'use strict';(function(root){const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=n=>Math.ceil(n).toLocaleString('ko-KR'),fixed=new Set(['smoke','coat','stealth','pursuit','efficiency']);const damageKinds=new Set('ambush shadow-stab shadow-rush weak-stab knife assassinate trick-card card-trap surprise shadow-finale venom-knife venom-burst venom-finale phantom-card double exchange phantom-finale sensor sticky remote chain-bombs convergence four-call overdrive'.split(' '));
function icon(d){const a=d.actions[0]||{},k=a.kind||a.op,shape=d.slot===3?'m18 3 4 9 10-4-4 20H8L4 8l10 4Zm-9 29h18':/summon|pet|four-call|double|echoes|turret/.test(k+' '+a.op)?'m18 3 13 15-13 15L5 18Zm0 8v14m-7-7h14':fixed.has(k)||/guard|ward|shield|buff|heal|resonance/.test(k+' '+a.op)?'M18 3 31 9v10c0 8-13 14-13 14S5 27 5 19V9Zm0 8v14m-7-7h14':'m8 26 18-18 7-5-5 9-17 17M6 21l9 9M8 26l-5 7 8-4';return `<svg viewBox="0 0 36 36" aria-hidden="true"><path d="${shape}"/></svg>`;}
function status(g,d){if(!d.unlocked)return{key:'locked',title:'아직 배우지 않은 기술',reason:`캐릭터 Lv.${d.unlock}에 사용할 수 있어요.`,button:'미습득'};if(d.rank>=d.maxRank)return{key:'max',title:'최대 강화 완료',reason:'이 기술의 강화를 모두 마쳤어요.',button:'최대 강화'};if(d.nextLevel>(d.maxLevel||200))return{key:'capped',title:'현재 성장 한도',reason:'현재 최고 캐릭터 레벨에서는 다음 강화 조건에 도달할 수 없어요.',button:'성장 조건 미충족'};if(g.h.level<d.nextLevel)return{key:'level',title:`캐릭터 Lv.${d.nextLevel} 필요`,reason:`현재 Lv.${g.h.level} · ${d.nextLevel-g.h.level}레벨 더 성장하면 강화할 수 있어요.`,button:'레벨 조건 미충족'};if(g.h.gold<d.upgradeCost)return{key:'gold',title:'골드가 부족해요',reason:`${fmt(d.upgradeCost-g.h.gold)} G를 더 모으면 강화할 수 있어요.`,button:'골드 부족'};return{key:'ready',title:'강화할 수 있어요',reason:'강화 단계는 전직 후에도 유지돼요.',button:'강화하기'};}
function comparison(d){const base=d.baseCooldown??d.cooldown??d.cd;if(base>0)return{label:'재사용 대기시간',current:d.cd+'초',next:d.nextCooldown+'초',note:'10강까지 단계당 2%, 이후 1%씩 감소 · 20강에서 총 28% 감소'};return{label:'공격 위력 보정',current:Math.round(d.powerMultiplier*100)+'%',next:Math.round(d.nextPowerMultiplier*100)+'%',note:'10강까지 단계당 14%, 이후 7% 추가 · 20강 위력 보정 296%'};}

function markup(g,slot=0,result=null,preview=false){if(!Number.isInteger(slot)||slot<0||slot>3)slot=0;const h=g.h,d=g.skillSpec(slot),st=status(g,d),c=comparison(d),max=d.rank>=d.maxRank,canNext=d.unlocked&&!max&&d.nextLevel<=(d.maxLevel||200),specs=[0,1,2,3].map(i=>g.skillSpec(i)),resource=g.resourceSpec(),job=g.p.classes[h.cell];return `<section class="skill-studio"><div class="ss-profile"><div class="ss-character"><canvas width="66" height="66" data-sheet="${esc(g.p.sheet)}" data-cell="${h.cell}" data-height="58" aria-hidden="true"></canvas><div><small>${esc(g.p.name)} · Lv.${h.level}</small><strong>${esc(job.name)}</strong></div></div><div class="ss-wallet"><small>보유 골드</small><b>${fmt(h.gold)}<span> G</span></b></div></div><div class="ss-layout"><nav class="ss-list" aria-label="강화할 스킬 선택">${specs.map((s,i)=>{const t=status(g,s);return `<button class="ss-pick ${i===slot?'selected':''} ${i===3?'is-ultimate':''}" data-skill-panel-slot="${i}" aria-pressed="${i===slot}" aria-controls="ss-detail" aria-label="${esc(s.name)} · ${s.unlocked?s.rank+'강':'미습득'} · ${t.title}"><span class="ss-icon">${icon(s)}<i>${i===3?'ULT':'0'+(i+1)}</i></span><span class="ss-pick-copy"><strong>${esc(s.name)}</strong><small>${s.unlocked?s.rank+'강':'Lv.'+s.unlock+' 습득'}</small></span><span class="ss-status-dot ${t.key}" aria-hidden="true"></span></button>`;}).join('')}<p class="ss-list-help">최대 20강 · Lv.200 완성<br>11강부터 10레벨마다 한 단계 해금</p></nav><article class="ss-detail ${slot===3?'is-ultimate':''}" id="ss-detail" aria-label="선택한 스킬 상세"><header class="ss-detail-title"><div><small>${slot===3?'ULTIMATE':'SKILL 0'+(slot+1)}</small><h3>${esc(d.name)}</h3></div><span>${d.unlocked?d.rank+'강':'미습득'}</span></header><div class="ss-result ${result?'show':''}" role="status" aria-live="polite">${result?`<b>강화 완료</b><span>${esc(result.name)} · ${result.from}강 → ${result.to}강</span>`:''}</div><div class="ss-chips"><span>${esc(resource.name)} <b>${d.cost}</b></span><span>재사용 <b>${d.cd?d.cd+'초':'자원 충전'}</b></span></div><section class="ss-growth"><div class="ss-section-heading"><h4>${max?'현재 효과':'강화 효과'}</h4><span>${max?'MAX':d.rank+'강 → '+(d.rank+1)+'강'}</span></div><div class="ss-comparison ${c.fixed?'unchanged':''}"><span>${c.label}</span><div><b>${esc(c.current)}</b>${!max?`<i>→</i><strong>${canNext?esc(c.next):'—'}</strong>`:'<strong>MAX</strong>'}</div></div><p class="ss-growth-note">${esc(c.note)}</p>${d.cd>0?`<p class="ss-growth-note">공격 위력 보정 ${Math.round(d.powerMultiplier*100)}%${!max?` → ${Math.round(d.nextPowerMultiplier*100)}%`:""} · 적용되는 공격·회복 효과 기준</p>`:""}${st.key!=='ready'&&st.key!=='max'?`<p class="ss-condition">${esc(st.reason)}</p>`:''}</section><details class="ss-effect"><summary>기술 효과 자세히 보기</summary><small>기본 효과 설명 · 강화된 재사용 시간은 위에 표시돼요.</small><p>${esc(d.description)}</p>${d.inherited?`<p class="ss-inherited">이전 궁극기 유지 · Lv.${d.replacementUnlock}에 ${esc(d.replacementName)} 습득</p>`:''}</details><button class="ss-preview-toggle" data-skill-panel-preview="1" aria-expanded="${preview}">${preview?'연출 접기':'연출 미리보기'}<span>${preview?'−':'▶'}</span></button>${preview?`<div class="ss-preview"><canvas id="preview-field" width="600" height="320" role="img" aria-label="${esc(d.name)} 연출 미리보기"></canvas><button data-skill-panel-replay="1" aria-label="선택한 스킬 연출 다시 재생">↻ 다시 재생</button></div>`:''}</article></div><footer class="ss-footer"><div class="ss-payment"><span>${max?'강화 완료':'필요 골드'}</span><strong>${max?'MAX':fmt(d.upgradeCost)+' G'}</strong>${!max?`<small>${st.key==='ready'?'강화 후 '+fmt(h.gold-d.upgradeCost)+' G':st.key==='gold'?fmt(d.upgradeCost-h.gold)+' G 부족':'보유 '+fmt(h.gold)+' G'}</small>`:''}</div><div class="ss-action"><div><b>${st.title}</b></div><button class="ss-upgrade" data-skill-upgrade="${slot+1}" ${st.key==='ready'?'':'disabled'}>${st.button}${st.key==='ready'?'<span>＋</span>':''}</button></div></footer></section>`;}
const API={markup,status,comparison,icon};if(typeof module!=='undefined')module.exports=API;root.RPG_SKILL_PANEL=API;})(typeof window!=='undefined'?window:globalThis);
